<?php
require __DIR__ . '/includes/bootstrap.php';
$d = listing((int)get('id'));
if (!$d || (!is_public($d) && !can_manage($d))) abort_page(404, 'This listing is not available.');
$full = can_manage($d) || has_unlock((int)$d['id']);
if ((current_user()['role'] ?? '') === 'student') query('INSERT INTO recent_views (user_id,dormitory_id) VALUES (?,?) ON DUPLICATE KEY UPDATE viewed_at=CURRENT_TIMESTAMP', [current_user()['id'],$d['id']]);
$images = rows('SELECT id FROM dormitory_images WHERE dormitory_id=?' . ($full ? '' : ' AND is_public=1') . ' ORDER BY id', [$d['id']]);
$amenities = rows('SELECT a.name FROM amenities a JOIN dormitory_amenities da ON da.amenity_id=a.id WHERE da.dormitory_id=? ORDER BY a.id' . ($full ? '' : ' LIMIT 3'), [$d['id']]);
$hiddenAmenities = $full ? 0 : max(0, (int)scalar('SELECT COUNT(*) FROM dormitory_amenities WHERE dormitory_id=?', [$d['id']]) - count($amenities));
$unlockFee = money(scalar("SELECT setting_value FROM settings WHERE setting_key='unlock_fee'"));
$visible = count($images) >= 5 ? 5 : min(count($images), 3); $more = count($images) - $visible;
$title = $d['name']; require __DIR__ . '/includes/header.php';
$slots = (int)$d['available_slots'];
?>
<section class="container section"><nav class="breadcrumb-nav" aria-label="Breadcrumb"><ol><li><a href="<?= url() ?>">Home</a></li><li><a href="<?= url('browse.php') ?>">Explore dorms</a></li><li aria-current="page"><?= e($d['name']) ?></li></ol></nav>
<div class="details-head"><div><span class="eyebrow"><?= $d['is_demo'] ? 'Fictional demo listing' : 'Find your next chapter' ?></span><h1><?= e($d['name']) ?></h1><p><i class="bi bi-geo-alt" aria-hidden="true"></i> <?= e($d['location']) ?>, Cebu City · <?= e($d['university']) ?></p></div><span class="avail-badge<?= $slots ? '' : ' full' ?>"><?= $slots ? $slots . ($slots === 1 ? ' slot available' : ' slots available') : 'Fully occupied' ?></span></div>
<?php if (!is_public($d)): ?><div class="alert alert-warning">Management preview · <?= e($d['status']) ?> · <?= $d['is_active'] ? 'Active' : 'Inactive' ?></div><?php endif; ?>
<?php if ($images): ?><div class="gallery-grid count-<?= $visible >= 5 ? 5 : $visible ?>" data-reveal="fade"><?php foreach ($images as $n => $i): $alt = $d['name'] . ' room photo' . ($d['is_demo'] ? ' (illustrative)' : ''); ?>
<?php if ($n < $visible): $badge = ($n === $visible - 1 && $more > 0); ?><a class="gallery-item<?= $badge ? ' gallery-more' : '' ?>" href="<?= image_url((int)$i['id']) ?>" data-lightbox<?= $badge ? ' data-more="+' . $more . ' more"' : '' ?>><img src="<?= image_url((int)$i['id']) ?>" alt="<?= e($alt) ?>" decoding="async"<?= $n === 0 ? ' fetchpriority="high"' : ' loading="lazy"' ?>></a>
<?php else: ?><a class="gallery-hidden" href="<?= image_url((int)$i['id']) ?>" data-lightbox><?= e($alt) ?> · Photo <?= $n + 1 ?></a><?php endif; ?><?php endforeach; ?></div><?php endif; ?>
<div class="details-grid"><div><section class="detail-section"><h2>A little about this place</h2><p><?= nl2br(e($d['description'])) ?></p><div class="detail-facts"><span><i class="bi bi-door-open" aria-hidden="true"></i><?= e($d['room_type']) ?></span><span><i class="bi bi-people" aria-hidden="true"></i><?= (int)$d['capacity'] ?>-person capacity</span><span><i class="bi bi-mortarboard" aria-hidden="true"></i><?= e($d['university']) ?></span></div></section>
<section class="detail-section"><details class="accordion-item" open><summary><?= $full ? 'Amenities' : 'A peek at the amenities' ?></summary><div class="accordion-body"><div class="accordion-inner"><div class="amenity-list"><?php foreach ($amenities as $a): ?><span><i class="bi bi-check2" aria-hidden="true"></i> <?= e($a['name']) ?></span><?php endforeach; ?></div><?php if ($hiddenAmenities): ?><p class="muted mt-3"><i class="bi bi-lock" aria-hidden="true"></i> +<?= $hiddenAmenities ?> more amenities with unlocked details.</p><?php endif; ?></div></div></details></section>
<?php if ($full): ?><section class="detail-section"><span class="eyebrow">Full details unlocked</span><h2>The details that make a difference</h2>
<div class="panel"><h3>Exact address</h3><p><?= e($d['exact_address']) ?></p><?php if ($d['map_url'] && preg_match('~^https://~i', $d['map_url'])): ?><a class="btn btn-outline-primary btn-sm" target="_blank" rel="noopener noreferrer" href="<?= e($d['map_url']) ?>">Open map <i class="bi bi-box-arrow-up-right" aria-hidden="true"></i></a><?php endif; ?></div>
<details class="accordion-item" open><summary>House rules</summary><div class="accordion-body"><div class="accordion-inner"><p><?= nl2br(e($d['house_rules'])) ?></p></div></div></details>
<details class="accordion-item"><summary>Curfew</summary><div class="accordion-body"><div class="accordion-inner"><p><?= e($d['curfew']) ?></p></div></div></details>
<details class="accordion-item"><summary>Security information</summary><div class="accordion-body"><div class="accordion-inner"><p><?= nl2br(e($d['security_info'])) ?></p><p class="muted">Owner-provided information; independently confirm conditions before renting.</p></div></div></details>
<div class="panel mt-4"><h3>Contact the owner</h3><p class="mb-0"><?= e($d['owner_name']) ?><br><?= e($d['contact_number']) ?><br><?= e($d['owner_email']) ?></p></div>
<?php if ($d['is_demo']): ?><div class="alert alert-info mt-3">This address and contact information are fictional. No real property can be booked.</div><?php endif; ?></section>
<?php else: ?><section class="locked-card"><div class="locked-preview" aria-hidden="true"><div class="ph-row"><i class="bi bi-geo-alt"></i><span class="ph-line w60"></span></div><div class="ph-row"><i class="bi bi-telephone"></i><span class="ph-line w40"></span></div><div class="ph-row"><i class="bi bi-shield-check"></i><span class="ph-line w80"></span></div><div class="ph-row"><i class="bi bi-journal-text"></i><span class="ph-line w60"></span></div></div>
<div class="locked-cta"><i class="bi bi-lock" aria-hidden="true"></i><h2>Get the full picture.</h2><p>Unlock the exact address, owner contact, all photos, house rules, and complete amenities.</p><ul class="unlock-list"><li><i class="bi bi-check2-circle" aria-hidden="true"></i>Exact address and map link</li><li><i class="bi bi-check2-circle" aria-hidden="true"></i>Owner name, phone and email</li><li><i class="bi bi-check2-circle" aria-hidden="true"></i>House rules, curfew and security notes</li><li><i class="bi bi-check2-circle" aria-hidden="true"></i>Every photo and the full amenity list</li></ul><br><a class="btn btn-primary btn-lg" href="<?= url('unlock.php?id=' . $d['id']) ?>">Unlock details · <?= $unlockFee ?></a><small>One-time simulated payment per listing. No real money.</small></div></section><?php endif; ?></div>
<aside class="rent-panel"><span>Monthly rent</span><div class="big-price"><?= money($d['monthly_rent']) ?><small> / month</small></div><p><?= $slots === 0 ? 'Fully occupied. No rooms currently available.' : e($slots) . ($slots === 1 ? ' reported slot available' : ' reported slots available') ?></p><hr><?php if (!$full): ?><a class="btn btn-primary w-100" href="<?= url('unlock.php?id=' . $d['id']) ?>">Unlock full details <i class="bi bi-key" aria-hidden="true"></i></a><?php else: ?><div class="alert alert-success mb-0">You have access to the full details.</div><?php endif; ?><button class="btn btn-outline-primary w-100 mt-3 compare-button" type="button" data-id="<?= $d['id'] ?>" aria-pressed="false"><i class="bi bi-plus-circle" aria-hidden="true"></i><span>Add to comparison</span></button><p class="small mt-3 mb-0">Unlocking gives access to information. It does not reserve a room.</p></aside></div></section>
<?php $related = rows(listing_select() . ' WHERE ' . public_condition() . ' AND d.id<>? AND (d.location=? OR d.university_id=?) ORDER BY d.id LIMIT 3',[$d['id'],$d['location'],$d['university_id']]); if ($related): ?><section class="container section pt-0"><h2>Another place to call home</h2><div class="cards-grid"><?php listing_cards($related); ?></div></section><?php endif; ?>
<?php require __DIR__ . '/includes/footer.php'; ?>
